    console.warn('IP lookup failed:', e.message);
  }

  // 3b. If IP failed, fall back to browser language
  const lang = browserLang.split('-')[0]; // e.g., "en-US" → "en"
  return greetings[lang] || greetings.en;
}

// 4️⃣  Example usage
(async () => {
  const userIP = '203.0.113.42'; // replace with real IP
  const browserLang = 'fr-CA';   // from Accept-Language header

  const greeting = await getLocalizedGreeting(userIP, browserLang);
  console.log(greeting); // → "Bonjour" (or "Hello" if IP fails)
})();
```

### What this does

1. **`getGreetingByIP`** – If the IP lookup succeeds, you get a greeting already translated into the country’s primary language.  
2. **Fallback** – If the IP lookup fails (e.g., rate‑limited, private IP), we fall back to the browser language.  
3. **`greetings` map** – Keeps a small, maintainable list of default greetings. You can extend it or replace it with a full i18n library if you need more nuance.

